== switch_layout required ['camera', 'layout', 'at']
{
"nest": {
"type": [
"boolean",
"string"
],
"description": "true: nest a role's clips first when one of them zooms or moves after `at`, instead of refusing. Default false."
},
"layout": {
"enum": [
"corner",
"side_by_side",
"stacked",
"camera_full",
"screen_only"
],
"type": "string",
"description": "corner, side_by_side, stacked, camera_full or screen_only."
},
"scope": {
"type": "integer",
"description": "Edit INSIDE a nest, by nest id \u2014 get_project lists them under nests, and a nest clip's source.project names the one it shows. With it, every id in this call \u2014 clips, tracks, actions \u2014 is looked up in THAT nest's own tracks and clips instead of the timeline's, and every time is the nest's own, measured from its zero (a nest has no speed, so the whole mapping is t minus the nest clip's start); media ids are unaffected, because a nest shares the document's media. The op itself is unchanged and one call is still one undo step. Omit it to edit whatever the app has OPEN \u2014 the timeline, or the nest set_scope entered, exactly as an edit made by hand goes where the window is looking \u2014 so this argument is how you act on a container you are not looking at, and get_project always says which one you are in. Eight ops have no meaning inside a nest and refuse by name when you ask for one: add_marker, set_marker, remove_marker, set_canvas, add_media, relink_media, remove_media, add_adjustment_clip. The first seven behave DIFFERENTLY when the scope is inherited from set_scope rather than asked for here, and the result says which: five of them, plus set_marker's name / chapter / color and remove_marker, simply land on the DOCUMENT and are named under document_ops. The two that carry a TIME \u2014 add_marker, and set_marker with a time \u2014 are refused instead, because a marker is at project time while the playhead inside a nest is not, so the tick you would send means the wrong frame. Leave the nest (set_scope with no arguments) or pass the tick in project time. And read the result rather than assuming it landed: an edit can be perfectly valid inside the nest and still be refused for the whole DOCUMENT's sake, since the clip and track caps and the 8-deep nesting limit are counted across every container at once.",
"minimum": 0
},
"curve": {
"enum": [
"linear",
"ease_in",
"ease_out",
"ease_in_out"
],
"type": "string",
"description": "How the switch eases. Default ease_in_out."
},
"at": {
"type": "integer",
"description": "When the switch starts, in project time (the container's inside a scope), in TICKS \u2014 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid."
},
"shape": {
"type": "string",
"enum": [
"square",
"rounded",
"circle"
],
"description": "corner only: square (the default), rounded or circle."
},
"through": {
"type": "integer",
"description": "Where the layout stops holding, in TICKS \u2014 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid. After `at`; the reach ends there if it is earlier than the next switch."
},
"screen": {
"description": "The screen clip's id, on a track behind the camera's. Absent: the clip playing at `at` on the front-most visible, non-matte track behind the camera's; none lays out the camera alone (refused for side_by_side and stacked).",
"minimum": 0,
"type": "integer"
},
"corner": {
"description": "corner only: bottom_right (the default), bottom_left, top_right or top_left.",
"type": "string",
"enum": [
"bottom_right",
"bottom_left",
"top_right",
"top_left"
]
},
"project": {
"type": "string",
"description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
},
"duration": {
"type": "integer",
"description": "How long the switch eases, in TICKS \u2014 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid. Default 0.5 s (300000), clamped to the clip and to its next layout action."
},
"camera": {
"description": "The camera clip's id: a clip with a picture playing at `at`.",
"minimum": 0,
"type": "integer"
},
"focus": {
"maxItems": 2,
"minItems": 2,
"type": [
"array",
"null"
],
"description": "[x, y]: the point of the camera's picture a crop is centred on, in the camera MEDIA's source pixels from the picture's centre, y down; clamped inside the picture. Omitted or null, the tool fills it as the menu does: the mean centroid of the camera clip's person masks when they are cached for every frame it plays (analyze_cutout's centroid, less the media's centre), else nothing, which centres the crop. A filled focus is dropped when nest: true nests the camera, since the nest clip is not the media; a focus you send is sent as given.",
"items": {
"type": "number"
}
}
}
