import Foundation

/// Switch Angle (road map "creator-jobs" SW1, spec §11 SW-13…SW-15): which
/// tracks are angles for a shot, and the sequence that re-picks the shot from
/// one. Clip ▸ Switch Angle ▸ (`EditorViewController+SwitchAngle.swift`) and
/// `switch_angle` (`AgentServer+Switch.swift`) both run it. It names no
/// `rc_*`: every op is tried through `ReelProject.applying(_:)`.
///
/// **Covering (SW-13, SW-15 (d)).** A track covers a span when its media
/// clips with a picture (`sourceSize(of:) != nil`) leave no tick of it
/// uncovered; a clip with its picture switched off, or on a hidden track,
/// still counts.
///
/// **The re-pick (SW-14, SW-15 (e)).** With B the shot between A and C on its
/// track: `delete` B, trim A's end to B's start and C's start to B's end
/// (each `alone`), one `copy_pieces` per angle clip the span crosses (B's
/// switches), then A and C trimmed back to their old edges and the two
/// transitions put back. The ops are tried one at a time on the container's
/// handle, because `applying([ReelOp])` does not stop at a refusal: a refusal
/// before the trim-backs, or a trim away held short of its target, refuses
/// the whole plan and nothing is committed; a trim-back that is refused or
/// held short is left out with its edge's transition, and the step is named
/// "Switch Angle (transition removed)".
enum SwitchAngle {
    /// One row of Clip ▸ Switch Angle ▸.
    struct Angle: Equatable {
        let track: UInt32
        let title: String
    }

    /// The most rows the submenu lists.
    static let menuLimit = 9
    static let actionName = "Switch Angle"
    static let removedName = "Switch Angle (transition removed)"

    /// The ops of a re-pick, its step's name, the new pieces' ids in time
    /// order, and how many of the shot's two transitions were dropped.
    struct Plan {
        let ops: [ReelOp]
        let actionName: String
        let pieces: [UInt32]
        let transitionsRemoved: Int
    }

    enum Answer {
        case plan(Plan)
        case refused(String)
    }

    /// The media clips with a picture on `track`, by start.
    static func pictureClips(on track: UInt32, in snapshot: ProjectSnapshot) -> [ClipSnapshot] {
        snapshot.clips(onTrack: track).filter { clip in
            guard case .media = clip.source else { return false }
            return snapshot.sourceSize(of: clip) != nil
        }
    }

    /// The first tick of `[from, to)` no picture clip on `track` covers, or
    /// nil when the track covers the whole span.
    static func firstUncovered(
        track: UInt32, from: Ticks, to: Ticks, in snapshot: ProjectSnapshot
    ) -> Ticks? {
        var reached = from
        for clip in pictureClips(on: track, in: snapshot) where clip.end > reached {
            if clip.start > reached { return reached }
            reached = clip.end
            if reached >= to { return nil }
        }
        return reached < to ? reached : nil
    }

    /// Every other track of the container covering `clip`'s whole span, front
    /// first, at most `menuLimit`. A name two listed tracks share gets " (n)",
    /// n the track's 1-based position from the back.
    static func angles(for clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> [Angle] {
        let covering = snapshot.tracks.reversed()
            .filter {
                $0.id != clip.track
                    && firstUncovered(track: $0.id, from: clip.start, to: clip.end, in: snapshot)
                        == nil
            }
            .prefix(menuLimit)
        let names = covering.map(\.name)
        return covering.map { track in
            guard names.filter({ $0 == track.name }).count > 1 else {
                return Angle(track: track.id, title: track.name)
            }
            let position = (snapshot.trackIndex(of: track.id) ?? 0) + 1
            return Angle(track: track.id, title: "\(track.name) (\(position))")
        }
    }

    /// Re-picks clip `id` from track `angle` in `container` (the handle of
    /// the container being edited). Throws for an unknown clip or track.
    static func plan(clip id: UInt32, angle: UInt32, in container: ReelProject) throws -> Answer {
        let snapshot = container.snapshot
        guard let shot = snapshot.clip(id) else {
            throw ReelCoreError(message: "no clip with id \(id)")
        }
        guard snapshot.track(angle) != nil else {
            throw ReelCoreError(message: "no track with id \(angle)")
        }
        if let why = refusal(shot, angle: angle, in: snapshot) { return .refused(why) }

        let (s, e) = (shot.start, shot.end)
        let neighbours = snapshot.clips(onTrack: shot.track).filter { $0.id != shot.id }
        let before = neighbours.last { $0.start < s && $0.end > s }
        let after = neighbours.first { $0.start > s && $0.start < e }
        var trial = Trial(project: container)

        if let why = try trial.require(.delete(clips: [id])) { return .refused(why) }
        if let a = before {
            if let why = try trial.require(.trimEnd(clip: a.id, to: s, alone: true)) {
                return .refused(why)
            }
            let reached = trial.project.snapshot.clip(a.id)?.end ?? a.end
            if reached != s { return .refused(held(a.id, reached, s, shot: id)) }
        }
        if let c = after {
            if let why = try trial.require(.trimStart(clip: c.id, to: e, alone: true)) {
                return .refused(why)
            }
            let reached = trial.project.snapshot.clip(c.id)?.start ?? c.start
            if reached != e { return .refused(held(c.id, reached, e, shot: id)) }
        }
        for range in pieceRanges(angle: angle, from: s, to: e, in: snapshot) {
            let op = ReelOp.copyPieces(
                clip: range.clip, track: shot.track, ranges: [(range.from, range.to)],
                video: shot.enabled.video, audio: shot.enabled.audio)
            if let why = try trial.require(op) { return .refused(why) }
        }
        let known = Set(snapshot.clips.map(\.id))
        let pieces = trial.project.snapshot.clips(onTrack: shot.track)
            .filter { !known.contains($0.id) }.map(\.id)

        var removed = 0
        if let a = before, let first = pieces.first {
            let back = ReelOp.trimEnd(clip: a.id, to: a.end, alone: true)
            if try trial.attempt(back, holds: { $0.clip(a.id)?.end == a.end }) {
                try trial.putBack(shot.transitionIn, on: first)
            } else {
                removed += 1
                try trial.clearTransition(on: first)
            }
        }
        if let c = after, !pieces.isEmpty {
            let back = ReelOp.trimStart(clip: c.id, to: c.start, alone: true)
            if try trial.attempt(back, holds: { $0.clip(c.id)?.start == c.start }) {
                try trial.putBack(c.transitionIn, on: c.id)
            } else {
                removed += 1
                try trial.clearTransition(on: c.id)
            }
        }
        return .plan(
            Plan(
                ops: trial.ops, actionName: removed > 0 ? removedName : actionName,
                pieces: pieces, transitionsRemoved: removed))
    }

    /// SW-15 (c)'s refusals, in order.
    private static func refusal(
        _ shot: ClipSnapshot, angle: UInt32, in snapshot: ProjectSnapshot
    ) -> String? {
        if angle == shot.track {
            return "track \(angle) is clip \(shot.id)'s own track; an angle is another track"
        }
        if snapshot.track(shot.track)?.locked == true {
            return "track \(shot.track) is locked, so clip \(shot.id) cannot be re-picked"
        }
        if let partner = shot.linked {
            return "clip \(shot.id) is linked to clip \(partner) (Detach Audio's pair); "
                + "Switch Angle re-picks a clip with no link"
        }
        if let tick = firstUncovered(track: angle, from: shot.start, to: shot.end, in: snapshot) {
            return "track \(angle) does not cover clip \(shot.id): nothing with a picture "
                + "plays on it at tick \(tick)"
        }
        return nil
    }

    /// The held-trim sentence (SW-15 (e)).
    private static func held(_ clip: UInt32, _ reached: Ticks, _ target: Ticks, shot: UInt32)
        -> String
    {
        "clip \(clip)'s edge is held at tick \(reached), short of tick \(target), so clip "
            + "\(shot) cannot be re-picked"
    }

    /// Each angle clip crossing `[from, to)` and the part of it a piece takes:
    /// `[max(start, from), min(end, the next one's start, to))`, empty ones
    /// skipped (SW-15 (d)).
    static func pieceRanges(
        angle: UInt32, from: Ticks, to: Ticks, in snapshot: ProjectSnapshot
    ) -> [(clip: UInt32, from: Ticks, to: Ticks)] {
        let crossing = pictureClips(on: angle, in: snapshot)
            .filter { $0.end > from && $0.start < to }
        var out: [(clip: UInt32, from: Ticks, to: Ticks)] = []
        for (index, clip) in crossing.enumerated() {
            let next = index + 1 < crossing.count ? crossing[index + 1].start : to
            let low = max(clip.start, from)
            let high = min(clip.end, next, to)
            if high > low { out.append((clip.id, low, high)) }
        }
        return out
    }

    /// The handle the plan has reached and the ops that reached it.
    struct Trial {
        var project: ReelProject
        var ops: [ReelOp] = []

        /// Applies `op`; nil when it applied or changed nothing, else the
        /// rule's sentence (nothing kept).
        mutating func require(_ op: ReelOp) throws -> String? {
            switch try project.applying(op) {
            case .applied(let next):
                project = next
                ops.append(op)
                return nil
            case .identity:
                ops.append(op)
                return nil
            case .refused(let refusal):
                return refusal.reason
            }
        }

        /// Keeps `op` only when it applied and the result `holds`.
        mutating func attempt(_ op: ReelOp, holds: (ProjectSnapshot) -> Bool) throws -> Bool {
            guard case .applied(let next) = try project.applying(op), holds(next.snapshot)
            else { return false }
            project = next
            ops.append(op)
            return true
        }

        /// The kind and style of `transition` on `clip`, when there was one.
        mutating func putBack(_ transition: TransitionSnapshot?, on clip: UInt32) throws {
            guard let transition else { return }
            _ = try require(.setTransition(clip: clip, kind: transition.kind))
            _ = try require(
                .setTransitionStyle(
                    clip: clip, curve: transition.curve, audio: transition.audio,
                    audioShape: transition.audioShape))
        }

        /// A left-out edge's clip keeps no transition.
        mutating func clearTransition(on clip: UInt32) throws {
            guard project.snapshot.clip(clip)?.transitionIn != nil else { return }
            _ = try require(.setTransition(clip: clip, kind: nil))
        }
    }
}

//! `copy_pieces` — a clip's pieces between given project times copied onto
//! another track at the same times (road map "creator-jobs" SW1, spec §11
//! SW-11, SW-12). It is the primitive Clip ▸ Switch Angle ▸ writes with: a
//! piece of a synced angle shows the angle's own frame at every time.
//!
//! A piece is EXACTLY the middle a `split` at its two ends would leave —
//! its source window, a ramp's map and rate, its actions clipped, a
//! graphic's `in` and `length`, its words rebased — because it is made by
//! `edit_split.rs`'s `split_clip` itself, on a scratch copy holding only the
//! source clip. This module states none of those rules; it only says where
//! the middle lands: a fresh id and fresh action ids from the result's own
//! counter, `track` the destination, `start` the range's start, no
//! transition and no link, and `enabled` overridden where `video`/`audio`
//! are given.
//!
//! In order (SW-11): `Err` for an unknown clip, then for an unknown track;
//! each pair put in order and snapped, a range empty on the grid dropped
//! (nothing left is an identity), the rest sorted by start; then the
//! refusals — a nest clip, a range outside the clip, overlapping ranges, a
//! locked destination, a destination holding a clip over a range. The exit
//! is `finish`.

use crate::edit_clip::clip_end;
use crate::edit_split::split_clip;
use crate::edit_time::locked_track;
use crate::model::{Clip, Project, Source};
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Project {
    /// Copies `clip`'s pieces between each range's ends onto `track` at the
    /// same project times (this module's doc, spec §6, §11 SW-11).
    pub fn copy_pieces(
        &self,
        clip: u32,
        track: u32,
        ranges: &[[Ticks; 2]],
        video: Option<bool>,
        audio: Option<bool>,
    ) -> Result<Outcome, String> {
        let source = self.require_clip(clip)?.clone();
        let destination = self.require_track(track)?;

        let mut spans: Vec<(Ticks, Ticks)> = ranges
            .iter()
            .map(|[a, b]| {
                let (low, high) = if a <= b { (*a, *b) } else { (*b, *a) };
                (self.snapped(low), self.snapped(high))
            })
            .filter(|(from, to)| to > from)
            .collect();
        if spans.is_empty() {
            return Ok(Outcome::Identity);
        }
        spans.sort_by_key(|&(from, to)| (from, to));

        if let Some(why) = self.pieces_refusal(&source, destination.id, destination.locked, &spans)
        {
            return Ok(Outcome::Refused(why));
        }

        let mut scratch = self.clone();
        scratch.clips = vec![source.clone()];
        let mut next = self.clone();
        let mut pieces: Vec<Clip> = Vec::with_capacity(spans.len());
        for &(from, to) in &spans {
            // `middle` answers `None` only when a cut is not strictly inside
            // the clip, which the checks above rule out (every span is
            // non-empty and inside the clip), so no range is ever skipped.
            let Some(mut piece) = middle(&scratch, &source, from, to) else {
                continue;
            };
            next.remint(&mut piece);
            piece.track = track;
            piece.start = from;
            piece.transition_in = None;
            piece.linked = None;
            if let Some(on) = video {
                piece.enabled.video = on;
            }
            if let Some(on) = audio {
                piece.enabled.audio = on;
            }
            pieces.push(piece);
        }
        next.clips.extend(pieces);
        self.finish(next)
    }

    /// The first refusal SW-11 names for `spans` (ordered, snapped, sorted),
    /// in its order: a nest clip, a range outside the clip, overlapping
    /// ranges, a locked destination, a destination holding a clip.
    fn pieces_refusal(
        &self,
        source: &Clip,
        track: u32,
        locked: bool,
        spans: &[(Ticks, Ticks)],
    ) -> Option<String> {
        if matches!(source.source, Source::Nest { .. }) {
            return Some(format!(
                "clip {} is a nest: a piece of it would replay the nest from its first frame",
                source.id
            ));
        }
        let (start, end) = (source.start, clip_end(source));
        if let Some((from, to)) = spans.iter().find(|(from, to)| *from < start || *to > end) {
            return Some(format!(
                "range [{from}, {to}] is outside clip {}, which runs from {start} to {end}",
                source.id
            ));
        }
        if let Some(pair) = spans.windows(2).find(|pair| pair[0].1 > pair[1].0) {
            let ((a, b), (c, d)) = (pair[0], pair[1]);
            return Some(format!("ranges [{a}, {b}] and [{c}, {d}] overlap"));
        }
        if locked {
            return Some(locked_track(track, "no piece can be copied onto it"));
        }
        let holder = self.clips_on_track(track).into_iter().find(|held| {
            let held_end = clip_end(held);
            spans
                .iter()
                .any(|(from, to)| held.start < *to && held_end > *from)
        })?;
        Some(format!(
            "track {track} holds clip {} between {} and {}",
            holder.id,
            holder.start,
            clip_end(holder)
        ))
    }
}

/// The middle `split_clip` leaves of `source` at `from` and `to` on a clone
/// of `scratch` (the project holding only `source`): split at `from` when it
/// is past the clip's start, the second half being the middle, then the
/// middle split at `to` when it is before the clip's end, the first half
/// being the middle (spec §11 SW-12).
fn middle(scratch: &Project, source: &Clip, from: Ticks, to: Ticks) -> Option<Clip> {
    let mut cut = scratch.clone();
    let mut id = source.id;
    if from > source.start {
        if !split_clip(&mut cut, id, from) {
            return None;
        }
        id = cut.clips.last()?.id;
    }
    if to < clip_end(source) && !split_clip(&mut cut, id, to) {
        return None;
    }
    cut.clip(id).cloned()
}
//! `switch_layout` — a camera clip and the screen behind it laid out at the
//! playhead (road map "creator-jobs" CO6, spec §11 CO-61, CO-62, CO-64).
//! One op, so Clip ▸ Camera Layout ▸ is one undo step, "Camera Layout".
//! The geometry is `layout.rs`'s; this file is who is laid out, how far,
//! and what refuses.
//!
//! - **The roles** (CO-64): the camera, playing at `at` with a picture; the
//!   screen given (on a track behind) or found — the clip playing at `at`
//!   on the front-most visible, non-matte track behind the camera's with a
//!   drawn picture. No screen refuses `side_by_side` and `stacked`; the
//!   other three lay out the camera alone.
//! - **The switch** (CO-61): per role, the clip under `at` gets a LAYOUT
//!   ACTION (all six placement keys) at clip time `at − start`, 0.5 s and
//!   `ease_in_out` unless told, clamped to the clip and to its next later
//!   layout action, at least one frame; at its first frame the layout is
//!   its base and a one-frame layout action ends there (a cut). A layout
//!   action starting at `at` is replaced; one running at `at` is shortened
//!   to end there. The REACH (`edit_layout_reach.rs`) gives every later
//!   picture clip on the role's track starting before the next layout
//!   action, `through` or the track's end the layout as its base.
//! - **The refusals** (CO-62), in order: the camera, the screen, a nest
//!   clip asked for a radius it cannot draw, a mover — a non-layout action
//!   that moves a role clip and ends after `at` (a full-placement screen
//!   exempt in the three layouts that leave it full) — then whatever the
//!   composed ops say. `nest: true` nests the moving role's clips first and
//!   lays out the nest clip, unless one of them is already laid out.
//!
//! Composed from `remove_action`, `set_action`, `add_action`,
//! `set_action_end`, `set_video` and `nest_clips`, each refusal inherited in
//! its own words.

use std::collections::HashSet;

use serde_json::json;

use crate::action_class::is_layout;
use crate::edit_adjustment::is_adjustment;
use crate::edit_clip::clip_end;
use crate::edit_layout_reach::{Role, RoleKind};
use crate::layout::{
    camera_placement, screen_placement, CameraLayout, LayoutChoice, LayoutCorner, LayoutShape,
    Placement, DEFAULT_SWITCH,
};
use crate::model::{Clip, Curve, Project, Source};
use crate::outcome::Outcome;
use crate::time::{format_timecode, Ticks};

/// `switch_layout`'s arguments, in the op's row order (`edit.rs`).
#[derive(Debug, Clone, PartialEq)]
pub struct LayoutSwitch {
    pub camera: u32,
    pub screen: Option<u32>,
    pub layout: CameraLayout,
    pub shape: Option<LayoutShape>,
    pub corner: Option<LayoutCorner>,
    pub at: Ticks,
    pub duration: Option<Ticks>,
    pub curve: Option<Curve>,
    pub focus: Option<[f64; 2]>,
    pub nest: Option<bool>,
    pub through: Option<Ticks>,
}

/// One role's writes: the clip under `at`, `at` in its clip time, its
/// layout action's end, and each later reach clip's new base.
type RoleWrites = (u32, Ticks, Placement, Vec<(u32, Placement)>);

/// One composed step: the project it applied, unchanged on an identity,
/// or the refusal handed straight back.
macro_rules! step {
    ($next:ident, $call:expr) => {
        match $call? {
            Outcome::Applied(applied) => $next = applied,
            Outcome::Identity => {}
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        }
    };
}

impl Project {
    /// Whether `clip` has a picture to lay out: a video group and a source
    /// size (CO-64).
    pub(crate) fn has_layout_picture(&self, clip: &Clip) -> bool {
        clip.video.is_some() && self.source_size(clip).is_some()
    }

    /// `at` as a timecode, for a sentence.
    pub(crate) fn layout_timecode(&self, t: Ticks) -> String {
        format_timecode(t, self.canvas.fps, self.canvas.timecode_frames)
    }

    /// Lays out `s.camera` and its screen at `s.at` (this module's doc).
    pub fn switch_layout(&self, s: &LayoutSwitch) -> Result<Outcome, String> {
        let at = self.snapped(s.at);
        if at < 0 {
            return Err(format!("at must not be negative, not {}", s.at));
        }
        let duration = match s.duration {
            None => DEFAULT_SWITCH,
            Some(given) => {
                let snapped = self.snapped(given);
                if snapped <= 0 {
                    return Err(format!("duration must be positive, not {given}"));
                }
                snapped
            }
        };
        let through = match s.through {
            None => None,
            Some(given) => {
                let snapped = self.snapped(given);
                if snapped <= at {
                    return Err(format!("through must be after at ({at}), not {given}"));
                }
                Some(snapped)
            }
        };
        let focus = match s.focus {
            None => (0.0, 0.0),
            Some([x, y]) if x.is_finite() && y.is_finite() => (x, y),
            Some([x, y]) => {
                return Err(format!("focus must be two finite numbers, not [{x}, {y}]"))
            }
        };
        let choice = LayoutChoice {
            layout: s.layout,
            shape: s.shape.unwrap_or_default(),
            corner: s.corner.unwrap_or_default(),
            focus,
        };

        // The camera (CO-64).
        let camera = self.require_clip(s.camera)?;
        if let Some(why) = self.role_refusal(camera, at) {
            return Ok(Outcome::Refused(why));
        }
        // The screen, given or found.
        let screen = match s.screen {
            Some(id) => {
                let screen = self.require_clip(id)?;
                if let Some(why) = self.role_refusal(screen, at) {
                    return Ok(Outcome::Refused(why));
                }
                let behind = match (
                    self.track_index(screen.track),
                    self.track_index(camera.track),
                ) {
                    (Some(back), Some(front)) => back < front,
                    _ => false,
                };
                if !behind {
                    return Ok(Outcome::Refused(format!(
                        "the screen (clip {}) must be on a track behind the camera's (clip {})",
                        screen.id, camera.id
                    )));
                }
                Some(screen)
            }
            None => self.screen_behind(camera, at),
        };
        if screen.is_none() && matches!(s.layout, CameraLayout::SideBySide | CameraLayout::Stacked)
        {
            return Ok(Outcome::Refused(format!(
                "no clip draws behind clip {} at {} to be the screen",
                camera.id,
                self.layout_timecode(at)
            )));
        }

        let mut roles = vec![self.role(RoleKind::Camera, camera, at, through)];
        if let Some(screen) = screen {
            roles.push(self.role(RoleKind::Screen, screen, at, through));
        }
        let movers: Vec<Option<String>> = roles
            .iter()
            .map(|role| self.mover_refusal(role, s.layout))
            .collect();
        let nesting = s.nest == Some(true);

        // A nest clip cannot draw a radius (CO-62).
        if s.layout == CameraLayout::Corner && choice.shape != LayoutShape::Square {
            let camera_role = &roles[0];
            let becomes = nesting && movers[0].is_some();
            let nested = camera_role
                .clips()
                .find(|c| matches!(c.source, Source::Nest { .. }))
                .map(|c| c.id)
                .or(becomes.then_some(camera_role.clip.id));
            if let Some(id) = nested {
                return Ok(Outcome::Refused(format!(
                    "clip {id} is a nest clip, which cannot draw a rounded corner or a circle."
                )));
            }
        }

        // The movers: refused, or nested first.
        if !nesting {
            if let Some(why) = movers.iter().flatten().next() {
                return Ok(Outcome::Refused(why.clone()));
            }
        } else if movers.iter().any(Option::is_some) {
            return self.nest_then_switch(s, &roles, &movers);
        }

        let curve = s.curve.unwrap_or(Curve::EaseInOut);
        self.compose_switch(&choice, &roles, at, duration, curve)
    }

    /// The switch composed once its refusals have passed (CO-61): every
    /// placement solved on the project as it is, then per role the layout
    /// action at `at` (replacing one starting there, shortening one running
    /// there, a cut at a first frame) and the bases of `later`. Shared by
    /// `switch_layout` and `reframe_layout.rs`'s replay (spec §11 VR-53 (b)).
    pub(crate) fn compose_switch(
        &self,
        choice: &LayoutChoice,
        roles: &[Role<'_>],
        at: Ticks,
        duration: Ticks,
        curve: Curve,
    ) -> Result<Outcome, String> {
        // Every placement is solved on the project as it is.
        let screen_size = roles
            .iter()
            .find(|role| role.kind == RoleKind::Screen)
            .and_then(|role| self.source_size(role.clip));
        let mut writes: Vec<RoleWrites> = Vec::new();
        for role in roles {
            let solve = |clip: &Clip, kept: Placement| -> Option<Placement> {
                let source = self.source_size(clip)?;
                Some(match role.kind {
                    RoleKind::Camera => camera_placement(self, choice, source, screen_size, &kept),
                    RoleKind::Screen => screen_placement(self, choice.layout, source),
                })
            };
            let t = at - role.clip.start;
            let kept = Placement::of(&self.evaluate_clip(role.clip, t).video);
            let Some(end) = solve(role.clip, kept) else {
                continue;
            };
            let bases = role
                .later
                .iter()
                .filter_map(|c| {
                    let base = Placement::of(c.video.as_ref()?);
                    solve(c, base).map(|p| (c.id, p))
                })
                .collect();
            writes.push((role.clip.id, t, end, bases));
        }

        let frame = self.frame();
        let mut next = self.clone();
        for (id, t, end, bases) in &writes {
            let (id, t) = (*id, *t);
            let clip = self.require_clip(id)?.clone();
            let video = end.to_json();
            let patch = json!({ "video": video });
            // One starting at `at` is replaced; one running at `at` ends there.
            if let Some(found) = clip.actions.iter().find(|a| is_layout(a) && a.start == t) {
                step!(next, next.remove_action(id, found.id));
            }
            if let Some(found) = clip
                .actions
                .iter()
                .find(|a| is_layout(a) && a.start < t && t < a.start.saturating_add(a.duration))
            {
                step!(
                    next,
                    next.set_action(id, found.id, None, Some(t - found.start), None)
                );
            }
            if t == 0 {
                // A cut: the base, and a one-frame action ending at it.
                step!(next, next.set_video(&[id], &video));
                let action = next.next_id;
                step!(next, next.add_action(id, 0, Some(frame)));
                step!(next, next.set_action_end(id, action, &patch, &[], None));
            } else {
                let mut length = duration.min(clip.duration - t);
                if let Some(later) = clip
                    .actions
                    .iter()
                    .filter(|a| is_layout(a) && a.start > t)
                    .map(|a| a.start)
                    .min()
                {
                    length = length.min(later - t);
                }
                let length = length.max(frame);
                let action = next.next_id;
                step!(next, next.add_action(id, t, Some(length)));
                step!(next, next.set_action(id, action, None, None, Some(curve)));
                step!(next, next.set_action_end(id, action, &patch, &[], None));
            }
            for (later, base) in bases {
                step!(next, next.set_video(&[*later], &base.to_json()));
            }
        }
        self.finish(next)
    }

    /// The camera's (or a given screen's) refusal: no picture, or not
    /// playing at `at` (CO-64).
    fn role_refusal(&self, clip: &Clip, at: Ticks) -> Option<String> {
        if !self.has_layout_picture(clip) {
            return Some(format!("clip {} has no picture to lay out", clip.id));
        }
        if !(clip.start <= at && at < clip_end(clip)) {
            return Some(format!(
                "clip {} does not play at {}",
                clip.id,
                self.layout_timecode(at)
            ));
        }
        None
    }

    /// The screen found behind `camera` at `at` (CO-64): the clip playing
    /// there on the front-most track behind the camera's that is shown and
    /// not a matte track, drawing a picture, not an adjustment clip.
    fn screen_behind(&self, camera: &Clip, at: Ticks) -> Option<&Clip> {
        let front = self.track_index(camera.track)?;
        self.tracks
            .get(..front)?
            .iter()
            .rev()
            .filter(|track| !track.hidden && track.matte.is_none())
            .find_map(|track| {
                self.clips.iter().find(|c| {

import Foundation

/// Make Vertical's summary (spec §11 VR-35) and its answer (VR-36): what `plan` did, said as
/// the sheet's and the tool's text and as `make_vertical_version`'s keys. A pure move out of
/// `VerticalVersion+Plan.swift` (road map "creator-jobs" VR5b's toll). Names no `rc_*`.
extension VerticalVersion {
    /// VR-35: the counts, then one line per re-laid switch (VR-54), then one line per entry
    /// with a reason; the graphic counts and lines VR4b's (`templates`, VR-44 (d)).
    static func summary(_ plan: Plan, templates: TemplateReport = TemplateReport()) -> String {
        func count(_ treatment: Treatment) -> Int {
            plan.entries.filter { $0.treatment == treatment }.count
        }
        var text = "Makes a \(plan.width) × \(plan.height) version."
        let followed = count(.followed)
        if followed > 0 { text += " Follows \(counted(followed, "clip"))." }
        if !plan.cursor.isEmpty {
            text += " Follows the cursor in \(counted(plan.cursor.count, "clip")), their own "
                + "zooms and pans replaced."
        }
        if !plan.speaker.isEmpty {
            text += " Follows whoever is talking in \(counted(plan.speaker.count, "clip"))."
        }
        if !plan.relaid.isEmpty {
            text += " Re-lays \(counted(plan.relaid.count, "camera layout")) for the new canvas."
        }
        let whole = count(.whole)
        if whole > 0 { text += " Shows \(counted(whole, "clip")) whole on a blurred copy." }
        let kept = count(.kept)
        if kept > 0 { text += " Keeps \(counted(kept, "clip")) as placed." }
        let refilled = count(.refilled)
        if refilled > 0 { text += " Re-fills \(counted(refilled, "background"))." }
        let removed = count(.removed)
        if removed > 0 {
            text += " Removes \(removed) blurred \(removed == 1 ? "copy" : "copies") the "
                + "framing replaces."
        }
        text += graphicsCounts(plan, templates)
        if plan.backgrounds { text += " Adds a Backgrounds track for the blurred copy." }
        if plan.moreTracks > 0 {
            text += " Adds \(plan.moreTracks) more \(plan.moreTracks == 1 ? "track" : "tracks")"
                + " behind it where clips overlap."
        }
        if plan.reEased > 0 { text += " \(counted(plan.reEased, "action")) re-eased at a cut." }
        if plan.carried > 0 {
            text += " \(counted(plan.carried, "action")) "
                + (plan.carried == 1 ? "carries" : "carry") + " a framing move."
        }
        if let relaid = plan.captions?.relaid.count, relaid > 0 {
            text += " Re-lays \(counted(relaid, "caption track")) for the new canvas."
        }
        let canvas = plan.project.snapshot.canvas
        var lines = [text] + plan.relaid.map { relaidLine($0, canvas: canvas) }
        for entry in plan.entries {
            guard let reason = entry.reason else { continue }
            let why = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
            switch entry.treatment {
            case .notFollowed: lines.append("Clip \(entry.clip) is not followed: \(why).")
            default: lines.append("Clip \(entry.clip) is followed, but \(why).")
            }
        }
        lines += (plan.captions?.kept ?? []).map(CaptionRelayout.keptLine)
        lines += graphicsLines(templates)
        return lines.joined(separator: "\n")
    }

    /// VR-39 (d)'s pending summary, while the analysis is still to be made; with `speaker` it
    /// says the sheet comes back to confirm the microphones' faces (VR-66 (e)).
    static func pendingSummary(files: Int, width: Int, height: Int, speaker: Bool = false)
        -> String
    {
        "Finds the faces, people and shot changes in \(counted(files, "file")) on this Mac "
            + "first, " + (speaker ? "then asks you to confirm who is on each microphone, " : "")
            + "then makes a \(width) × \(height) version."
    }

    /// The answer's keys every door shares (VR-36): `canvas`, `clips` in id order,
    /// `backgrounds`, `more_tracks`, `re_eased`, `moves_carried`, `summary`, `graphics`,
    /// `cursor` (VR-52), `relaid` (VR-54) and `speaker` (VR-64 (f)).
    static func answerFields(_ plan: Plan, templates: TemplateReport = TemplateReport())
        -> [String: Any]
    {
        let clips: [[String: Any]] = plan.entries.map { entry in
            var row: [String: Any] = [
                "clip": Int(entry.clip), "treatment": entry.treatment.rawValue,
            ]
            if let reason = entry.reason { row["reason"] = reason }
            return row
        }
        var fields: [String: Any] = [
            "canvas": ["width": plan.width, "height": plan.height],
            "clips": clips,
            "backgrounds": plan.backgrounds,
            "more_tracks": plan.moreTracks,
            "re_eased": plan.reEased,
            "moves_carried": plan.carried,
            "summary": summary(plan, templates: templates),
            "cursor": plan.cursor.map { Int($0) },
            "relaid": relaidFields(plan.relaid),
            "speaker": plan.speaker.map { framed -> [String: Any] in
                [
                    "clip": Int(framed.clip), "mics": framed.mics.map { Int($0) },
                    "mic_faces": framed.faces.map { Int($0) },
                ]
            },
            "graphics": graphicsFields(plan, templates),
        ]
        if let captions = plan.captions {
            fields["captions"] = CaptionRelayout.answerFields(captions)
        }
        return fields
    }

    static func counted(_ n: Int, _ noun: String) -> String {
        "\(n) \(noun)\(n == 1 ? "" : "s")"
    }
}
