        let frame = self.frame();
        let mut next = self.clone();
        for (id, t, end, bases) in &writes {
            let (id, t) = (*id, *t);
            let clip = self.require_clip(id)?.clone();
            let video = end.to_json();
            let patch = json!({ "video": video });
